//
// Hand-written. NOT generated by CLI Printing Press - see handfixes.json,
// record `typed-resources-table-parent-prefixed`.
//
// Why this file exists
// --------------------
// Resource Guru exposes an API resource literally named `resources` - the
// connector's headline resource - so the press emitted its typed domain table
// under the same bare name as the framework's generic catch-all `resources`
// table. The catch-all CREATE is element [0] of the migrations slice, so the
// typed `CREATE TABLE IF NOT EXISTS "resources"` silently no-opped and every
// typed write would have run against the catch-all's column set.
//
// The shipped mitigation (v0.1.0, v0.1.1) made `upsertResourcesTx` a no-op and
// deleted the typed FTS triggers. That stopped the failing writes but left the
// real defect: `backfillColumns` still added 21 flattened columns (name, email,
// first_name, bookable, job_title, ...) plus five indexes to the CATCH-ALL, so
// the MCP `sql` tool answered rows of NULLs for
// `SELECT name, email FROM resources` - a silent wrong answer - instead of
// erroring. (That tool is the connector's only arbitrary-SQL surface; the CLI
// ships no `sql` command, and the MCP one opens the store read-only.)
//
// The fix parent-prefixes the typed table and its FTS shadow to
// `accounts_resources` / `accounts_resources_fts` (the parent is the account
// the collection hangs off, /v1/{account}/resources), restores the full
// 21-column typed INSERT and the three FTS triggers, and points
// `backfillColumns` at the renamed table. This is the same disambiguation
// applied to afi (`tenants_resources`) and rootly
// (`incident_permission_sets_resources`) in PR #295.
//
// This file is resourceguru's counterpart to afi/rootly's
// legacy_resources_shape_test.go, plus the projection receipts those two did
// not need (their typed tables carry only a parent key; this one carries the
// 21 flattened columns whose NULLs were the residual defect).
//
//	 1. TestFreshDB_TypedResourcesProjectionIsSeparateFromCatchAll - the
//	    reachability proof plus the structural guarantee that a count of the
//	    typed table can never be a count of the catch-all (the false-GREEN class
//	    PR #295 named).
//	 2. TestReopen_CatchAllResourcesKeepsGenericColumnsOnly - the residual
//	    defect is gone: the flattened columns are on the typed table, and
//	    selecting them from the catch-all now errors instead of answering NULLs.
//	    It reopens the store because backfillColumns runs before the migrations
//	    slice and so short-circuits on a first open - a single-open version of
//	    this assertion passes against the pre-fix code.
//	 3. TestUpsertBatch_FillsTypedResourcesProjection - the behavioural receipt:
//	    a fixture batch lands with every flattened column non-NULL.
//	 4. TestUpsertBatch_SeedsTypedResourcesFTS - the restored triggers actually
//	    index, and SearchResources returns the seeded record through the typed
//	    index (not through the generic one).
//	 5. TestMigrate_LegacyGenericResourcesTableUpgrades - the reachable legacy
//	    case: a pre-gate generic `resources` opens, keeps its rows, and the typed
//	    projection starts empty (it fills on the next resync).
//	 6. TestOpen_BareTypedResourcesShapeIsRejected - the actual, unchanged
//	    behaviour for the non-producible typed shape, pinned rather than hidden.
//	 7. TestListIDs_ResourcesReadsTypedTableNotCatchAll - the three resolve sites
//	    answer from the typed projection. Hardening, not a live-defect fix; see
//	    the correction in that test's own comment.
//	 8. TestMigrate_V4CatchAllProjectionIsDropped - the repair for stores v0.1.0
//	    and v0.1.1 already polluted: the 20 added columns and the five projection
//	    indexes come off the catch-all, its own two indexes and every row stay.
//	 9. TestMigrate_V4CatchAllProjectionKeepsPopulatedColumn - the drop cannot
//	    destroy data: a column holding a value is kept, per-column, even though
//	    no released binary could have written one.
//	10. TestSchemaVersion_MigratedStoreIsRefusedByAV4Binary - the bump is what
//	    makes the repair durable, and the gate is really wired into Open.
//
// The reader-side receipts for `search --type resources` and for the
// `resources_bookings` fan-out routing live in the sibling package, at
// cli/internal/cli/typed_resources_reader_test.go.
//
// Evidence that a bare `resources` table carrying the TYPED shape is
// unreachable from any released binary (verified 2026-08-26 against every state
// this file's sibling store.go has ever had - `git log` returns exactly one
// content commit, de473087d, which is both released tags resourceguru-v0.1.0
// and resourceguru-v0.1.1; the two blobs are byte-identical):
//
//   - `CREATE TABLE IF NOT EXISTS resources (... resource_type TEXT NOT NULL
//     ...)` is element [0] of the migrations slice, strictly before the typed
//     CREATE. The slice runs in order, so the typed CREATE always lost the
//     IF NOT EXISTS race and the on-disk table always carried the generic shape.
//   - The whole slice runs inside one BEGIN IMMEDIATE transaction, so no crash
//     can leave a half-applied schema where only the typed CREATE committed.
//   - Independently: both releases stamp user_version 4, so a database any
//     released binary has opened is at version 4 and the `current < 2`
//     composite-key migration never fires on it at all.
//   - The store lives at ~/.local/share/<binary>/data.db, one file per
//     connector, so no other connector's schema can supply the shape either.

package store

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"
	"testing"

	_ "modernc.org/sqlite"
)

// typedResourcesFlattenedColumns is the flattened column set the press
// generated for the `resources` resource. It is the set that used to be
// backfilled onto the catch-all and answer NULLs.
var typedResourcesFlattenedColumns = []string{
	"archived",
	"bookable",
	"color",
	"created_at",
	"creator_id",
	"email",
	"first_name",
	"human",
	"image",
	"job_title",
	"last_name",
	"last_updated_by",
	"minutes_per_day",
	"name",
	"notes",
	"phone",
	"updated_at",
	"url",
	"user_id",
	"vacation_allowance",
	"parent_id",
}

// tableColumnSet returns the column set of the named table.
func tableColumnSet(t *testing.T, db *sql.DB, table string) map[string]bool {
	t.Helper()
	rows, err := db.Query(fmt.Sprintf(`PRAGMA table_info(%q)`, table))
	if err != nil {
		t.Fatalf("table_info %s: %v", table, err)
	}
	defer rows.Close()

	cols := map[string]bool{}
	for rows.Next() {
		var cid int
		var name, typ string
		var notnull, pk int
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &typ, &notnull, &dflt, &pk); err != nil {
			t.Fatalf("scan table_info %s: %v", table, err)
		}
		cols[name] = true
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("table_info %s rows: %v", table, err)
	}
	return cols
}

// TestFreshDB_TypedResourcesProjectionIsSeparateFromCatchAll is the
// reachability proof for the fixture rename in
// TestMigrate_AddsColumnsOnUpgrade_Resources, and the structural guard against
// the false-GREEN class PR #295 named: TestUpsertBatch_PopulatesResourcesTable
// counted the catch-all and reported the typed projection healthy while it was
// empty forever. A typed table that cannot carry `resource_type` cannot be the
// catch-all under another name, so that count now means what it says.
func TestFreshDB_TypedResourcesProjectionIsSeparateFromCatchAll(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open fresh db: %v", err)
	}
	defer s.Close()

	generic := tableColumnSet(t, s.DB(), "resources")
	if !generic["resource_type"] {
		t.Fatalf("fresh `resources` table has no resource_type column; the generic catch-all lost the CREATE race and every later open would fail")
	}
	if !generic["data"] || !generic["synced_at"] || !generic["updated_at"] {
		t.Fatalf("fresh `resources` table is not the generic catch-all shape: %v", generic)
	}

	typed := tableColumnSet(t, s.DB(), "accounts_resources")
	if len(typed) == 0 {
		t.Fatalf("typed projection table `accounts_resources` was not created")
	}
	if typed["resource_type"] {
		t.Fatalf("typed table `accounts_resources` carries resource_type; it is the catch-all under a new name, not the typed projection")
	}
	for _, col := range typedResourcesFlattenedColumns {
		if !typed[col] {
			t.Fatalf("typed table `accounts_resources` missing generated column %q: %v", col, typed)
		}
	}

	// The typed FTS shadow is parent-prefixed too, so it cannot displace the
	// generic resources_fts index (id, resource_type, content) that
	// upsertGenericResourceTx maintains by hand.
	genericFTS := tableColumnSet(t, s.DB(), "resources_fts")
	if !genericFTS["resource_type"] || !genericFTS["content"] {
		t.Fatalf("generic resources_fts is not the catch-all index shape: %v", genericFTS)
	}
	typedFTS := tableColumnSet(t, s.DB(), "accounts_resources_fts")
	if !typedFTS["name"] || !typedFTS["notes"] {
		t.Fatalf("typed accounts_resources_fts missing its indexed columns: %v", typedFTS)
	}
}

// TestReopen_CatchAllResourcesKeepsGenericColumnsOnly pins the residual defect
// this change removes. Before it, backfillColumns added all 21 flattened
// columns to the catch-all, so the MCP `sql` tool answered
// `SELECT name, email FROM resources` with a row per synced record and every
// projected value NULL - a silent
// wrong answer on the connector's headline resource. Selecting them now fails
// loudly, which is the correct answer for a table that does not have them.
//
// The REOPEN is load-bearing and this test is worthless without it.
// backfillColumns runs BEFORE the migrations slice (see its doc comment: the
// ordering exists so a later CREATE INDEX finds its column), so on a first open
// no table exists yet and every entry short-circuits on table-not-found. The
// pollution lands on the SECOND open, once the catch-all is on disk. Measured
// against the pre-fix store.go, a single-open version of this test PASSES while
// the defect is fully present - it was a false-GREEN of exactly the class PR
// #295 named. With the reopen, the pre-fix code answers
// `err=<nil> name=NULL email=NULL` and the test fails as it must.
func TestReopen_CatchAllResourcesKeepsGenericColumnsOnly(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	first, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open fresh db: %v", err)
	}
	if _, _, err := first.UpsertBatch("resources", []json.RawMessage{
		json.RawMessage(`{"id":"r1","name":"Ada Lovelace","email":"ada@example.com"}`),
	}); err != nil {
		first.Close()
		t.Fatalf("UpsertBatch on first open: %v", err)
	}
	if err := first.Close(); err != nil {
		t.Fatalf("close first open: %v", err)
	}

	// Second open: the catch-all now exists, so backfillColumns no longer
	// short-circuits and would ALTER the 21 flattened columns onto it.
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("reopen db: %v", err)
	}
	defer s.Close()

	generic := tableColumnSet(t, s.DB(), "resources")

	// The catch-all's own declared shape, exactly. Anything else on it is
	// projection debris.
	wantGeneric := map[string]bool{
		"id":            true,
		"resource_type": true,
		"data":          true,
		"synced_at":     true,
		"updated_at":    true,
	}
	for col := range generic {
		if !wantGeneric[col] {
			t.Fatalf("catch-all `resources` carries extra column %q; SELECT %s FROM resources answers NULLs instead of erroring", col, col)
		}
	}
	for _, col := range typedResourcesFlattenedColumns {
		if wantGeneric[col] {
			// `updated_at` is declared by the catch-all itself and is also a
			// projected field name; it is not projection debris.
			continue
		}
		if generic[col] {
			t.Fatalf("catch-all `resources` carries flattened column %q; SELECT %s FROM resources answers NULLs instead of erroring", col, col)
		}
	}

	// The row synced by the first open is still readable through the catch-all,
	// which is the data-retention posture the rename rests on.
	if data, err := s.Get("resources", "r1"); err != nil {
		t.Fatalf("get r1 after reopen: %v", err)
	} else if !strings.Contains(string(data), "Ada Lovelace") {
		t.Fatalf("catch-all row after reopen = %s, want the synced record", data)
	}

	var name, email sql.NullString
	err = s.DB().QueryRow(`SELECT name, email FROM resources`).Scan(&name, &email)
	if err == nil {
		t.Fatalf("SELECT name, email FROM resources succeeded (name=%v email=%v); the catch-all still carries the flattened columns and answers NULLs instead of erroring", name, email)
	}
	if !strings.Contains(err.Error(), "no such column") {
		t.Fatalf("SELECT name, email FROM resources error = %v, want a 'no such column' error", err)
	}
}

// TestUpsertBatch_FillsTypedResourcesProjection is the behavioural receipt that
// the restored typed INSERT works: every flattened column arrives non-NULL for
// a record that carries the field, through the same UpsertBatch path a
// paginated sync uses.
func TestUpsertBatch_FillsTypedResourcesProjection(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{
			"id": "res-1",
			"archived": false,
			"bookable": true,
			"color": "#ff0000",
			"created_at": "2026-01-01T00:00:00Z",
			"creator_id": 11,
			"email": "ada@example.com",
			"first_name": "Ada",
			"human": true,
			"image": "https://example.com/ada.png",
			"job_title": "Engineer",
			"last_name": "Lovelace",
			"last_updated_by": 12,
			"minutes_per_day": 480,
			"name": "Ada Lovelace",
			"notes": "prefers mornings",
			"phone": "+15550100",
			"updated_at": "2026-02-01T00:00:00Z",
			"url": "https://example.com/resources/res-1",
			"user_id": 13,
			"vacation_allowance": 20,
			"parent_id": "acct-A"
		}`),
	}
	if stored, failed, err := s.UpsertBatch("resources", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	} else if failed != 0 || stored != len(items) {
		t.Fatalf("UpsertBatch stored=%d failed=%d, want stored=%d failed=0", stored, failed, len(items))
	}

	for _, col := range typedResourcesFlattenedColumns {
		var got sql.NullString
		query := fmt.Sprintf(`SELECT %q FROM "accounts_resources"`, col)
		if err := s.DB().QueryRow(query).Scan(&got); err != nil {
			t.Fatalf("select %s from accounts_resources: %v", col, err)
		}
		if !got.Valid {
			t.Fatalf("accounts_resources.%s is NULL; the typed projection did not fill", col)
		}
	}

	// Spot-check two values rather than only non-NULL-ness, so a projection
	// that wrote the right number of columns in the wrong order fails here.
	var name, email string
	if err := s.DB().QueryRow(`SELECT "name", "email" FROM "accounts_resources"`).Scan(&name, &email); err != nil {
		t.Fatalf("select name,email: %v", err)
	}
	if name != "Ada Lovelace" || email != "ada@example.com" {
		t.Fatalf("accounts_resources projection = (%q, %q), want (\"Ada Lovelace\", \"ada@example.com\")", name, email)
	}

	// The parent key lands in its own column, so parent-scoped offline lookups
	// answer. This is what the deleted typed INSERT could never deliver.
	var byParent int
	if err := s.DB().QueryRow(`SELECT COUNT(*) FROM "accounts_resources" WHERE "parent_id" = ?`, "acct-A").Scan(&byParent); err != nil {
		t.Fatalf("count by parent_id: %v", err)
	}
	if byParent != 1 {
		t.Fatalf("parent_id=acct-A count = %d, want 1", byParent)
	}
}

// TestUpsertBatch_SeedsTypedResourcesFTS proves the restored
// accounts_resources_ai/ad/au triggers index, and that SearchResources reads
// the TYPED index rather than delegating to the generic one. The probe token
// lives only in `notes`, which the generic index also covers, so the test
// deletes the generic index's rows first: a hit after that can only have come
// from accounts_resources_fts.
func TestUpsertBatch_SeedsTypedResourcesFTS(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	const probe = "zqxjppresourceprobe"
	items := []json.RawMessage{
		json.RawMessage(`{"id":"res-1","name":"Ada Lovelace","notes":"` + probe + `"}`),
	}
	if stored, failed, err := s.UpsertBatch("resources", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	} else if failed != 0 || stored != 1 {
		t.Fatalf("UpsertBatch stored=%d failed=%d, want stored=1 failed=0", stored, failed)
	}

	var indexed int
	if err := s.DB().QueryRow(`SELECT COUNT(*) FROM "accounts_resources_fts"`).Scan(&indexed); err != nil {
		t.Fatalf("count accounts_resources_fts: %v", err)
	}
	if indexed != 1 {
		t.Fatalf("accounts_resources_fts holds %d rows, want 1 (the AFTER INSERT trigger did not fire)", indexed)
	}

	// Empty the generic index so the assertion below cannot pass through it.
	if _, err := s.DB().Exec(`DELETE FROM resources_fts`); err != nil {
		t.Fatalf("clear generic resources_fts: %v", err)
	}
	if generic, err := s.Search(probe, 10); err != nil {
		t.Fatalf("generic Search: %v", err)
	} else if len(generic) != 0 {
		t.Fatalf("generic Search still returns %d rows after clearing resources_fts; the isolation this test relies on is broken", len(generic))
	}

	results, err := s.SearchResources(probe, 10)
	if err != nil {
		t.Fatalf("SearchResources: %v", err)
	}
	if len(results) != 1 {
		t.Fatalf("SearchResources(%q) returned %d rows, want 1 from the typed index", probe, len(results))
	}
	if !strings.Contains(string(results[0]), probe) {
		t.Fatalf("SearchResources returned %s, want the seeded record", results[0])
	}
}

// TestMigrate_LegacyGenericResourcesTableUpgrades covers the legacy case that
// IS reachable: a store written before the schema-version gate, so
// user_version 0 with a single-column-primary-key generic `resources` table.
// Opening it must succeed, preserve the rows, and install the composite key.
func TestMigrate_LegacyGenericResourcesTableUpgrades(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")

	raw, err := sql.Open("sqlite", dbPath)
	if err != nil {
		t.Fatalf("open raw: %v", err)
	}
	if _, err := raw.Exec(`CREATE TABLE resources (
		id TEXT PRIMARY KEY,
		resource_type TEXT NOT NULL,
		data JSON NOT NULL,
		synced_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
	)`); err != nil {
		raw.Close()
		t.Fatalf("create legacy generic resources: %v", err)
	}
	if _, err := raw.Exec(`INSERT INTO resources (id, resource_type, data) VALUES ('r1', 'resources', '{"id":"r1","name":"legacy row"}')`); err != nil {
		raw.Close()
		t.Fatalf("seed legacy row: %v", err)
	}
	if _, err := raw.Exec(`PRAGMA user_version = 0`); err != nil {
		raw.Close()
		t.Fatalf("stamp pre-gate version: %v", err)
	}
	raw.Close()

	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open legacy generic-shape db: %v", err)
	}
	defer s.Close()

	v, err := s.SchemaVersion()
	if err != nil {
		t.Fatalf("read schema version: %v", err)
	}
	if v != StoreSchemaVersion {
		t.Fatalf("upgraded version = %d, want %d", v, StoreSchemaVersion)
	}

	// The catch-all row survives the upgrade and stays queryable. This is the
	// data-retention claim the rename rests on: full record JSON lives here.
	data, err := s.Get("resources", "r1")
	if err != nil {
		t.Fatalf("get legacy row after upgrade: %v", err)
	}
	if string(data) != `{"id":"r1","name":"legacy row"}` {
		t.Fatalf("legacy row payload = %s, want the original JSON", data)
	}

	// The typed projection is created empty; it fills on the next successful
	// resync, not from the catch-all.
	var typed int
	if err := s.DB().QueryRow(`SELECT COUNT(*) FROM "accounts_resources"`).Scan(&typed); err != nil {
		t.Fatalf("count typed projection: %v", err)
	}
	if typed != 0 {
		t.Fatalf("typed projection = %d rows after upgrade, want 0 (it fills on the next resync)", typed)
	}
}

// TestOpen_BareTypedResourcesShapeIsRejected pins the ACTUAL behaviour for a
// `resources` table carrying the typed shape - the case the generated fixture
// used to construct before the rename.
//
// This state is not producible by any released resourceguru binary (see the
// file header for the receipts), so no defensive migration is warranted for it
// and none is implemented. What is NOT acceptable is leaving the behaviour
// undocumented and looking away, so it is asserted here: at every schema
// version the open fails loudly, naming the missing column, and never silently
// drops data.
//
// If a future change adds a defensive pre-migration guard (rename the table
// aside, recreate the generic shape, warn), this test is the one to update -
// deliberately, with the new behaviour asserted.
func TestOpen_BareTypedResourcesShapeIsRejected(t *testing.T) {
	for version := 0; version <= StoreSchemaVersion; version++ {
		t.Run(fmt.Sprintf("user_version_%d", version), func(t *testing.T) {
			dbPath := filepath.Join(t.TempDir(), "data.db")

			raw, err := sql.Open("sqlite", dbPath)
			if err != nil {
				t.Fatalf("open raw: %v", err)
			}
			if _, err := raw.Exec(`CREATE TABLE "resources" (
				id TEXT PRIMARY KEY,
				data JSON NOT NULL,
				synced_at DATETIME DEFAULT CURRENT_TIMESTAMP
			)`); err != nil {
				raw.Close()
				t.Fatalf("create bare typed-shape resources: %v", err)
			}
			if _, err := raw.Exec(`INSERT INTO "resources" (id, data) VALUES ('r1', '{"id":"r1"}')`); err != nil {
				raw.Close()
				t.Fatalf("seed row: %v", err)
			}
			if _, err := raw.Exec(fmt.Sprintf(`PRAGMA user_version = %d`, version)); err != nil {
				raw.Close()
				t.Fatalf("stamp version: %v", err)
			}
			raw.Close()

			s, err := Open(dbPath)
			if err == nil {
				s.Close()
				t.Fatalf("Open succeeded on a typed-shape `resources` table at user_version %d; if that is a deliberate new behaviour, update this test to assert it", version)
			}
			if !strings.Contains(err.Error(), "resource_type") {
				t.Fatalf("Open error = %v, want an error naming the missing resource_type column", err)
			}

			// The failed open must not have destroyed the operator's row: the
			// migrations run inside one BEGIN IMMEDIATE transaction that rolls
			// back as a unit.
			check, err := sql.Open("sqlite", dbPath)
			if err != nil {
				t.Fatalf("reopen raw: %v", err)
			}
			defer check.Close()
			var n int
			if err := check.QueryRow(`SELECT COUNT(*) FROM "resources"`).Scan(&n); err != nil {
				t.Fatalf("count rows after failed open: %v", err)
			}
			if n != 1 {
				t.Fatalf("row count after failed open = %d, want 1 (the failed migration must roll back)", n)
			}
		})
	}
}

// TestListIDs_ResourcesReadsTypedTableNotCatchAll is the reader-side receipt.
// Renaming the typed table fixes the WRITE path; every resource-type -> table
// resolve site had to learn the new name too. ListIDs / ListIDsScoped /
// ListField resolve a resource type to a table through sqlite_master, so a bare
// `resources` resolved to the CATCH-ALL, which holds every synced record of
// every type: `SELECT id FROM "resources"` answers client, project and booking
// ids alongside resource ids. typedTableName makes all three resolve to the
// typed projection instead.
//
// What this receipt does NOT claim, and an earlier draft of this comment
// wrongly did: that this connector's `resources_bookings` fan-out was
// contaminated. It was not, and it never could have been - see
// TestDependentParentRows_ResourcesFanOutIsTypeFiltered in internal/cli, which
// pins the actual routing. No caller in this connector reaches ListIDs,
// ListIDsScoped or ListField with `resources` today. typedTableName is
// hardening for those three entry points: it makes the resolve correct for any
// caller that does reach them, so a later dependent declaration or a reprint
// that changes the fan-out shape cannot silently inherit the catch-all.
//
// The assertions below are what the fix actually guarantees: each of the three
// resolve sites, called with `resources`, answers from the typed projection and
// not from the catch-all.
func TestListIDs_ResourcesReadsTypedTableNotCatchAll(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	if _, _, err := s.UpsertBatch("clients", []json.RawMessage{
		json.RawMessage(`{"id":"client-1","name":"Acme"}`),
	}); err != nil {
		t.Fatalf("UpsertBatch clients: %v", err)
	}
	if _, _, err := s.UpsertBatch("resources", []json.RawMessage{
		json.RawMessage(`{"id":"res-1","name":"Ada Lovelace","parent_id":"acct-A"}`),
	}); err != nil {
		t.Fatalf("UpsertBatch resources: %v", err)
	}

	// Both rows are in the catch-all, which is what makes this discriminating.
	var catchAll int
	if err := s.DB().QueryRow(`SELECT COUNT(*) FROM resources`).Scan(&catchAll); err != nil {
		t.Fatalf("count catch-all: %v", err)
	}
	if catchAll != 2 {
		t.Fatalf("catch-all holds %d rows, want 2 (the test cannot discriminate otherwise)", catchAll)
	}

	ids, err := s.ListIDs("resources")
	if err != nil {
		t.Fatalf("ListIDs: %v", err)
	}
	if len(ids) != 1 {
		t.Fatalf("ListIDs(%q) returned %v (%d ids), want exactly the 1 resource id; a client id means the resolve hit the catch-all", "resources", ids, len(ids))
	}
	if bare := BareResourceID(ids[0]); bare != "res-1" {
		t.Fatalf("ListIDs(%q)[0] bare id = %q, want %q", "resources", bare, "res-1")
	}

	// ListField resolves through the same lookup and feeds the
	// multi-placeholder fan-out path.
	names, err := s.ListField("resources", "name")
	if err != nil {
		t.Fatalf("ListField: %v", err)
	}
	if len(names) != 1 || names[0] != "Ada Lovelace" {
		t.Fatalf("ListField(%q, %q) = %v, want [Ada Lovelace]", "resources", "name", names)
	}

	// ListIDsScoped degrades to ListIDs when no scope column is known, which is
	// this connector's configuration (parentTenantScopeColumns is empty), so
	// pin that path too.
	scoped, err := s.ListIDsScoped("resources", "", "")
	if err != nil {
		t.Fatalf("ListIDsScoped: %v", err)
	}
	if len(scoped) != 1 {
		t.Fatalf("ListIDsScoped(%q, \"\", \"\") returned %v, want 1 id", "resources", scoped)
	}
}

// legacyV4CatchAllColumns is the on-disk shape a released resourceguru binary
// (v0.1.0 / v0.1.1) leaves behind on its SECOND open: the generic catch-all's
// own five columns plus every flattened column its backfillColumns ALTER-ed
// onto that table. The fixture below is built from typedResourcesFlattenedColumns,
// which is transcribed from the released backfill list, so it stays independent
// of store.go's legacyCatchAllProjectionColumns - the list the migration drops.
// If those two ever disagree, TestMigrate_V4CatchAllProjectionIsDropped fails.
func legacyV4CatchAllColumns() []string {
	cols := []string{"id", "resource_type", "data", "synced_at", "updated_at"}
	for _, c := range typedResourcesFlattenedColumns {
		if c == "updated_at" {
			// Declared by the catch-all itself; not an added column.
			continue
		}
		cols = append(cols, c)
	}
	return cols
}

// seedLegacyV4Store writes a database in exactly the state a released binary
// leaves: the polluted catch-all, its two real indexes plus the five projection
// indexes, one synced row per resource type, and user_version = 4.
func seedLegacyV4Store(t *testing.T, dbPath string, extraRowSQL ...string) {
	t.Helper()
	raw, err := sql.Open("sqlite", dbPath)
	if err != nil {
		t.Fatalf("open raw: %v", err)
	}
	defer raw.Close()

	create := `CREATE TABLE "resources" (
		"id" TEXT NOT NULL,
		"resource_type" TEXT NOT NULL,
		"data" JSON NOT NULL,
		"synced_at" DATETIME DEFAULT CURRENT_TIMESTAMP,
		"updated_at" DATETIME DEFAULT CURRENT_TIMESTAMP,
		PRIMARY KEY ("resource_type", "id")
	)`
	if _, err := raw.Exec(create); err != nil {
		t.Fatalf("create legacy catch-all: %v", err)
	}
	for _, col := range typedResourcesFlattenedColumns {
		if col == "updated_at" {
			continue
		}
		if _, err := raw.Exec(fmt.Sprintf(`ALTER TABLE "resources" ADD COLUMN %q TEXT`, col)); err != nil {
			t.Fatalf("add legacy projection column %s: %v", col, err)
		}
	}
	for _, stmt := range []string{
		`CREATE INDEX idx_resources_type ON resources(resource_type)`,
		`CREATE INDEX idx_resources_synced ON resources(synced_at)`,
		`CREATE INDEX "idx_resources_creator_id" ON "resources"("creator_id")`,
		`CREATE INDEX "idx_resources_user_id" ON "resources"("user_id")`,
		`CREATE INDEX "idx_resources_created_at" ON "resources"("created_at")`,
		`CREATE INDEX "idx_resources_updated_at" ON "resources"("updated_at")`,
		`CREATE INDEX "idx_resources_parent_id" ON "resources"("parent_id")`,
	} {
		if _, err := raw.Exec(stmt); err != nil {
			t.Fatalf("create legacy index (%s): %v", stmt, err)
		}
	}
	for _, stmt := range append([]string{
		`INSERT INTO "resources" (id, resource_type, data) VALUES ('res-1', 'resources', '{"id":"res-1","name":"Ada Lovelace","email":"ada@example.com"}')`,
		`INSERT INTO "resources" (id, resource_type, data) VALUES ('client-1', 'clients', '{"id":"client-1","name":"Acme"}')`,
	}, extraRowSQL...) {
		if _, err := raw.Exec(stmt); err != nil {
			t.Fatalf("seed legacy row (%s): %v", stmt, err)
		}
	}
	if _, err := raw.Exec(fmt.Sprintf(`PRAGMA user_version = %d`, 4)); err != nil {
		t.Fatalf("stamp user_version 4: %v", err)
	}
}

func indexNamesOn(t *testing.T, db *sql.DB, table string) map[string]bool {
	t.Helper()
	rows, err := db.Query(`SELECT name FROM sqlite_master WHERE type='index' AND tbl_name=?`, table)
	if err != nil {
		t.Fatalf("list indexes on %s: %v", table, err)
	}
	defer rows.Close()
	out := map[string]bool{}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			t.Fatalf("scan index name: %v", err)
		}
		out[name] = true
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("list indexes on %s: %v", table, err)
	}
	return out
}

// TestMigrate_V4CatchAllProjectionIsDropped is the receipt for the residual
// defect on ALREADY-RELEASED stores. Renaming the typed table stops NEW damage;
// it does nothing for the databases v0.1.0 and v0.1.1 already polluted, where
// `SELECT name FROM resources` keeps answering a row of NULLs per synced record
// forever. The v4-to-v5 migration removes the 20 added columns and the five
// projection indexes from the catch-all, so those stores answer the same way a
// fresh install does.
//
// The fixture is the real legacy shape, not a stub: a two-row catch-all whose
// rows must survive byte-identically, plus the catch-all's own idx_resources_type
// and idx_resources_synced, which must NOT be dropped.
func TestMigrate_V4CatchAllProjectionIsDropped(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	seedLegacyV4Store(t, dbPath)

	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open legacy v4 store: %v", err)
	}
	defer s.Close()

	v, err := s.SchemaVersion()
	if err != nil {
		t.Fatalf("read schema version: %v", err)
	}
	if v != StoreSchemaVersion {
		t.Fatalf("migrated version = %d, want %d", v, StoreSchemaVersion)
	}

	generic := tableColumnSet(t, s.DB(), "resources")
	want := map[string]bool{"id": true, "resource_type": true, "data": true, "synced_at": true, "updated_at": true}
	for col := range generic {
		if !want[col] {
			t.Fatalf("catch-all `resources` still carries %q after the v5 migration; SELECT %s FROM resources answers NULLs instead of erroring", col, col)
		}
	}
	for col := range want {
		if !generic[col] {
			t.Fatalf("catch-all `resources` lost its own column %q", col)
		}
	}
	if got, wantLen := len(generic), len(want); got != wantLen {
		t.Fatalf("catch-all column count = %d, want %d: %v", got, wantLen, generic)
	}
	// Independence check: the fixture built 20 added columns from
	// typedResourcesFlattenedColumns and all 20 are gone, so store.go's
	// legacyCatchAllProjectionColumns covers the released backfill list exactly.
	if got, wantLen := len(legacyV4CatchAllColumns()), len(want)+len(legacyCatchAllProjectionColumns); got != wantLen {
		t.Fatalf("legacy fixture has %d columns but the migration drops %d + %d declared; the two lists disagree", got, len(legacyCatchAllProjectionColumns), len(want))
	}

	indexes := indexNamesOn(t, s.DB(), "resources")
	for _, idx := range legacyCatchAllProjectionIndexes {
		if indexes[idx] {
			t.Fatalf("projection index %q still on the catch-all after the v5 migration", idx)
		}
	}
	for _, idx := range []string{"idx_resources_type", "idx_resources_synced"} {
		if !indexes[idx] {
			t.Fatalf("the migration dropped the catch-all's own index %q", idx)
		}
	}

	// Both rows survive byte-identically. The migration only ever touched the
	// schema; the JSON payloads are the durable copy of every synced record.
	for _, tc := range []struct{ resourceType, id, want string }{
		{"resources", "res-1", `{"id":"res-1","name":"Ada Lovelace","email":"ada@example.com"}`},
		{"clients", "client-1", `{"id":"client-1","name":"Acme"}`},
	} {
		data, err := s.Get(tc.resourceType, tc.id)
		if err != nil {
			t.Fatalf("get %s/%s after migration: %v", tc.resourceType, tc.id, err)
		}
		if string(data) != tc.want {
			t.Fatalf("%s/%s payload = %s, want %s", tc.resourceType, tc.id, data, tc.want)
		}
	}

	// The point of the whole exercise: the silent wrong answer is gone.
	var name sql.NullString
	if err := s.DB().QueryRow(`SELECT name FROM resources`).Scan(&name); err == nil {
		t.Fatalf("SELECT name FROM resources still succeeds (name=%v) on a migrated legacy store", name)
	} else if !strings.Contains(err.Error(), "no such column") {
		t.Fatalf("SELECT name FROM resources error = %v, want a 'no such column' error", err)
	}
}

// TestMigrate_V4CatchAllProjectionKeepsPopulatedColumn proves the drop cannot
// destroy data, in the direction that matters.
//
// The claim justifying the DROP is that no released binary ever wrote one of
// these columns: upsertResourcesTx is a no-op in both released tags, and the
// only statement any released code ran against the catch-all is
// upsertGenericResourceTx's INSERT over (id, resource_type, data, synced_at,
// updated_at). Rather than trust that reasoning, the migration COUNTs each
// column before dropping it. This test forces the branch the history says is
// unreachable - a catch-all row with a non-NULL `name` - and requires the
// column and its value to survive the upgrade.
func TestMigrate_V4CatchAllProjectionKeepsPopulatedColumn(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	seedLegacyV4Store(t, dbPath,
		`UPDATE "resources" SET "name" = 'hand written value' WHERE id = 'res-1'`)

	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open legacy v4 store with populated projection column: %v", err)
	}
	defer s.Close()

	generic := tableColumnSet(t, s.DB(), "resources")
	if !generic["name"] {
		t.Fatalf("the migration dropped `name` from the catch-all even though it held data")
	}
	var got sql.NullString
	if err := s.DB().QueryRow(`SELECT name FROM resources WHERE id = 'res-1'`).Scan(&got); err != nil {
		t.Fatalf("select preserved value: %v", err)
	}
	if !got.Valid || got.String != "hand written value" {
		t.Fatalf("preserved value = %v, want %q", got, "hand written value")
	}
	// Every column that really was empty still goes, so the guard is per-column
	// rather than an all-or-nothing bail-out.
	if generic["email"] {
		t.Fatalf("the migration kept the empty column `email` because a DIFFERENT column held data")
	}
}

// TestSchemaVersion_MigratedStoreIsRefusedByAV4Binary is the receipt for the
// bump itself.
//
// Dropping the projection columns is only durable if the binaries that added
// them can no longer open the store. resourceguru-v0.1.0 and v0.1.1 both carry
// StoreSchemaVersion = 4 and both run backfillColumns unconditionally on every
// open, so either of them opening a migrated store would ALTER all 21 columns
// straight back onto the catch-all - damage this binary cannot detect, because
// a re-added column and a never-dropped one are indistinguishable. The version
// gate is what prevents it: a v4 binary reads user_version 5, finds it newer
// than the version it supports, and refuses.
//
// Two halves, both needed. The first drives the gate with the older binary's
// supported version against the version a store this binary creates actually
// carries. The second proves the gate is really wired into Open, by presenting
// THIS binary with a store one version newer than it understands.
func TestSchemaVersion_MigratedStoreIsRefusedByAV4Binary(t *testing.T) {
	const lastReleasedSupportedVersion = 4

	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open fresh db: %v", err)
	}
	stamped, err := s.SchemaVersion()
	if err != nil {
		s.Close()
		t.Fatalf("read schema version: %v", err)
	}
	if err := s.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	if stamped <= lastReleasedSupportedVersion {
		t.Fatalf("a store created by this binary stamps user_version %d, which the released v%d binary accepts; the projection drop is not durable without a bump", stamped, lastReleasedSupportedVersion)
	}

	if err := schemaVersionUnsupported(stamped, lastReleasedSupportedVersion); err == nil {
		t.Fatalf("the v%d version gate accepts a store at user_version %d", lastReleasedSupportedVersion, stamped)
	} else if !strings.Contains(err.Error(), "upgrade the CLI binary") {
		t.Fatalf("v%d gate error = %v, want the upgrade-the-binary message", lastReleasedSupportedVersion, err)
	}
	// The same gate must still admit a store at its own version, or the bump
	// would lock this binary out of the databases it creates.
	if err := schemaVersionUnsupported(stamped, StoreSchemaVersion); err != nil {
		t.Fatalf("this binary's own gate rejects a store it stamped: %v", err)
	}

	// The gate is reachable through Open, not just callable in isolation.
	futurePath := filepath.Join(t.TempDir(), "future.db")
	raw, err := sql.Open("sqlite", futurePath)
	if err != nil {
		t.Fatalf("open raw: %v", err)
	}
	if _, err := raw.Exec(`CREATE TABLE resources (
		id TEXT NOT NULL,
		resource_type TEXT NOT NULL,
		data JSON NOT NULL,
		synced_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		PRIMARY KEY (resource_type, id)
	)`); err != nil {
		raw.Close()
		t.Fatalf("create catch-all: %v", err)
	}
	if _, err := raw.Exec(fmt.Sprintf(`PRAGMA user_version = %d`, StoreSchemaVersion+1)); err != nil {
		raw.Close()
		t.Fatalf("stamp future version: %v", err)
	}
	raw.Close()

	future, err := Open(futurePath)
	if err == nil {
		future.Close()
		t.Fatalf("Open accepted a store at user_version %d; the version gate is not wired into Open", StoreSchemaVersion+1)
	}
	if !strings.Contains(err.Error(), "upgrade the CLI binary") {
		t.Fatalf("Open error = %v, want the upgrade-the-binary message", err)
	}
}
